import * as THREE from 'three';

// The clock starts at 11:58:00 (in seconds since midnight).
export const START_TIME_SECONDS = 11 * 3600 + 58 * 60 + 0;

const DOOR_OPEN_ANGLE = -Math.PI / 3;
const DOOR_OPEN_DURATION = 3; // seconds after each top of the hour
const PENDULUM_AMPLITUDE = 0.3;

/**
 * Builds the cuckoo clock scene graph:
 * - housing: a closed box
 * - hourHand / minuteHand: pivoted groups (pivot at clock center)
 * - pendulum: a group swinging about its top pivot
 * - door: a group hinged on its left edge
 */
export function buildClock() {
  const clock = {};

  // Housing box
  const housing = new THREE.Group();
  housing.name = 'housing';
  const housingMesh = new THREE.Mesh(
    new THREE.BoxGeometry(4, 6, 2),
    new THREE.MeshStandardMaterial({ color: 0x8b5a2b })
  );
  housingMesh.name = 'housingBox';
  housing.add(housingMesh);
  clock.housing = housing;

  // Face so hands have something to sit on (slightly in front of the box)
  const face = new THREE.Mesh(
    new THREE.CircleGeometry(1.6, 32),
    new THREE.MeshStandardMaterial({ color: 0xfff3d6 })
  );
  face.name = 'face';
  face.position.set(0, 0.5, 1.01);
  housing.add(face);

  // Hands: pivoted groups. Each hand mesh is offset upward inside the group,
  // so rotating the group's rotation.z turns the hand around the pivot.
  function makeHand(length, width, color) {
    const pivot = new THREE.Group();
    const mesh = new THREE.Mesh(
      new THREE.BoxGeometry(width, length, 0.02),
      new THREE.MeshStandardMaterial({ color })
    );
    // Shift geometry up by half its length so the pivot is at the hand base.
    mesh.position.y = length / 2;
    pivot.add(mesh);
    return pivot;
  }

  const minuteHand = makeHand(1.3, 0.08, 0x222222);
  minuteHand.name = 'minuteHand';
  minuteHand.position.set(0, 0.5, 1.03);
  const hourHand = makeHand(0.9, 0.12, 0x222222);
  hourHand.name = 'hourHand';
  hourHand.position.set(0, 0.5, 1.05);
  housing.add(minuteHand, hourHand);

  clock.minuteHand = minuteHand;
  clock.hourHand = hourHand;

  // Pendulum: swings about a pivot at its top.
  const pendulum = new THREE.Group();
  pendulum.name = 'pendulum';
  const rod = new THREE.Mesh(
    new THREE.BoxGeometry(0.04, 2.2, 0.04),
    new THREE.MeshStandardMaterial({ color: 0xc9a227 })
  );
  rod.position.y = -1.1; // hang below the pivot
  const bob = new THREE.Mesh(
    new THREE.CylinderGeometry(0.25, 0.25, 0.06, 24),
    new THREE.MeshStandardMaterial({ color: 0xc9a227 })
  );
  bob.rotation.x = Math.PI / 2;
  bob.position.y = -2.2;
  pendulum.add(rod, bob);
  pendulum.position.set(0, -1.4, 1.0); // pivot point below the face
  housing.add(pendulum);
  clock.pendulum = pendulum;

  // Door: hinged on its left edge -> shift the group to the hinge position and
  // offset the door panel to the right within the group.
  const door = new THREE.Group();
  door.name = 'door';
  const panelWidth = 1.0;
  const panel = new THREE.Mesh(
    new THREE.BoxGeometry(panelWidth, 1.0, 0.06),
    new THREE.MeshStandardMaterial({ color: 0x5a3219 })
  );
  panel.position.x = panelWidth / 2; // left edge of panel sits at the hinge
  door.add(panel);
  door.position.set(-panelWidth / 2, -2.2, 1.05); // hinge on the left edge
  housing.add(door);
  clock.door = door;

  // Simulation state
  clock.events = []; // cuckoo event timestamps (simSeconds at top of hour)
  clock._lastSimSeconds = null;

  return clock;
}

function isOpenWindow(clockTimeSeconds) {
  return clockTimeSeconds % 3600 < DOOR_OPEN_DURATION;
}

/**
 * Advances the simulation to `simSeconds` (seconds since the clock started at
 * 11:58:00), updating hands, pendulum, and door, and recording any cuckoo
 * events (tops of the hour) that occurred up to this moment.
 *
 * Returns the array of cuckoo event timestamps recorded so far.
 */
export function tickClock(clock, simSeconds) {
  const prev =
    clock._lastSimSeconds === null ? -Infinity : clock._lastSimSeconds;
  clock._lastSimSeconds = simSeconds;

  const clockTime = START_TIME_SECONDS + simSeconds;

  // --- Cuckoo events: one per top of the hour reached during (prev, simSeconds]
  const firstBoundary =
    prev === -Infinity
      ? 120 // first top of hour after start (11:58:00 -> 12:00:00)
      : START_TIME_SECONDS + prev;
  for (let b = firstBoundary; b <= clockTime; b += 3600) {
    if (b > clockTime) break;
    const t = b - START_TIME_SECONDS;
    if (!clock.events.includes(t)) {
      clock.events.push(t);
    }
  }
  clock.events.sort((a, b) => a - b);

  // --- Pendulum
  clock.pendulum.rotation.z =
    PENDULUM_AMPLITUDE * Math.sin(2 * Math.PI * simSeconds);

  // --- Door
  clock.door.rotation.y = isOpenWindow(clockTime) ? DOOR_OPEN_ANGLE : 0;

  // --- Hands
  const totalMinutes = clockTime / 60;
  const minuteFraction = totalMinutes / 60; // fraction of a full turn
  const hourFraction = (totalMinutes % 720) / 720; // 12-hour dial

  clock.minuteHand.rotation.z = -2 * Math.PI * minuteFraction;
  clock.hourHand.rotation.z = -2 * Math.PI * hourFraction;

  return clock.events;
}

