import { describe, it, expect } from 'vitest';
import { buildClock, tickClock } from '../src/cuckoo.js';

describe('cuckoo clock', () => {
  it('door is closed just before the top of the hour (simSeconds = 119)', () => {
    const clock = buildClock();
    tickClock(clock, 119);
    expect(clock.door.rotation.y).toBe(0);
    expect(clock.events).toHaveLength(0);
  });

  it('door is open at -PI/3 at simSeconds = 121 with one event at t = 120', () => {
    const clock = buildClock();
    tickClock(clock, 119);
    tickClock(clock, 121);

    expect(clock.door.rotation.y).toBeCloseTo(-Math.PI / 3, 12);
    expect(Math.abs(clock.door.rotation.y - -Math.PI / 3)).toBeLessThan(1e-9);
    expect(clock.events).toEqual([120]);
  });

  it('door is closed again at simSeconds = 124', () => {
    const clock = buildClock();
    tickClock(clock, 119);
    tickClock(clock, 121);
    tickClock(clock, 124);

    expect(clock.door.rotation.y).toBe(0);
    expect(clock.events).toEqual([120]);
  });

  it('hands read ~12:00:04 at simSeconds = 124 (minute-hand angle within 1e-3)', () => {
    const clock = buildClock();
    tickClock(clock, 124);

    // Start 11:58:00 + 124 s = 12:00:04.
    // Minute hand: 4/60 of a full turn past twelve, clockwise => negative z.
    const expectedMinuteAngle = -(2 * Math.PI) * (4 / 60);
    expect(
      Math.abs(clock.minuteHand.rotation.z - expectedMinuteAngle)
    ).toBeLessThan(1e-3);

    // Hour hand: 12h + 4s past twelve on a 12-hour dial.
    const expectedHourAngle = -(2 * Math.PI) * ((4 / 3600) / 12);
    expect(
      Math.abs(clock.hourHand.rotation.z - expectedHourAngle)
    ).toBeLessThan(1e-3);
  });

  it('pendulum amplitude never exceeds 0.3', () => {
    const clock = buildClock();
    let maxAmplitude = 0;
    for (let t = 0; t <= 3700; t += 0.01) {
      tickClock(clock, t);
      maxAmplitude = Math.max(maxAmplitude, Math.abs(clock.pendulum.rotation.z));
    }
    expect(maxAmplitude).toBeLessThanOrEqual(0.3 + 1e-12);
    expect(maxAmplitude).toBeGreaterThan(0.29);
  });

  it('records subsequent hourly events', () => {
    const clock = buildClock();
    tickClock(clock, 3721); // second top of the hour after start
    expect(clock.events).toEqual([120, 3720]);
    expect(clock.door.rotation.y).toBeCloseTo(-Math.PI / 3, 12);
  });
});

